def count_divisors_sq(x):
    # Find the prime factorization of x
    d = 2
    temp_x = x
    factors = {}
    while d * d <= temp_x:
        while temp_x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_x //= d
        d += 1
    if temp_x > 1:
        factors[temp_x] = factors.get(temp_x, 0) + 1

    # The number of divisors of x^2 is product of (2*a_i + 1)
    divisors_x2 = 1
    for count in factors.values():
        divisors_x2 *= (2 * count + 1)
    return divisors_x2

